INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c3333333-3333-3333-3333-333333333333', 'Compas Escolar De Lapiz', 'compas-escolar-de-lapiz-75347', 'Compás Escolar de Lápiz Precisión básica para trazos circulares en trabajos académicos Compás escolar con sistema de sujeción para lápiz, diseñado para la realización de circunferencias, arcos y trazos geométricos con precisión en papel. Su estructura metálica o plástica según versión permite un ajuste estable del radio, facilitando el control del trazo y la estabilidad durante el uso, convirtiéndolo en una herramienta funcional para actividades académicas de dibujo técnico, geometría y ejercicios escolares de uso frecuente.', 1229.00, 20, 38, true, false, 'https://www.abastece.co/abastece/images/75347.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Comprobante De Egreso Autocopiante Por 50 Minerva 2006 A', 'comprobante-de-egreso-autocopiante-por-50-minerva-2006-a-0069', 'Comprobante de Egreso Autocopiante por 50 Minerva 2006 A Registro contable eficiente para control de salidas de efectivo Comprobante de egreso autocopiante marca Minerva 2006 A, presentado en talonario de 50 juegos, diseñado para el registro de salidas de dinero con copia simultánea que facilita el control administrativo y contable. Su sistema autocopiante permite generar duplicados sin necesidad de papel adicional, asegurando trazabilidad documental, orden en los procesos financieros y una gestión eficiente de registros en operaciones contables de uso continuo.', 62098.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/0069.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Comprobante De Venta 1/32 X 40 Juegos Autocopiante', 'comprobante-de-venta-132-x-40-juegos-autocopiante-77744', 'Comprobante De Venta 1/32 X 40 Juegos Autocopiante ¡Formato compacto, copia clara sin papel carbón y control eficiente para sus transacciones! Optimice la gestión de sus ventas rápidas y el registro de transacciones comerciales con el talonario de Comprobante De Venta en formato 1/32 por 40 juegos autocopiantes. Diseñado para ofrecer una duplicación limpia, precisa y sin necesidad de utilizar papel carbón, este talonario garantiza que cada copia conserve la nitidez de la escritura original. Su tamaño compacto de 1/32 de pliego es ideal para pequeños negocios, mostradores, ventas ambulantes, domicilios y entregas en campo, ocupando un espacio mínimo y facilitando la organización contable diaria. ¡Adquiera el suyo hoy y mantenga un control administrativo impecable y profesional en su negocio!', 3293.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/77744.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Contrato Individual De Trabajo A Termino Fijo Inferior A 1 Año Minerva 1010', 'contrato-individual-de-trabajo-a-termino-fijo-inferior-a-1-ano-minerva-1010-77568', 'Contrato Individual De Trabajo A Termino Fijo Inferior A 1 Año Minerva 1010 ¡Asegure el cumplimiento de la normativa laboral vigente y formalice las vinculaciones temporales de su compañía con total respaldo legal! Garantice la correcta estipulación de las condiciones contractuales para contrataciones temporales, prevenga contingencias jurídicas o vacíos legales en el área de recursos humanos y mantenga la documentación administrativa en perfecto orden con un formato estandarizado de validez probatoria. El uso de las formas comerciales e impresas como el contrato individual de trabajo a término fijo inferior a 1 año Minerva 1010 facilita la estandarización de procesos de contratación, selección e incorporación de personal en la compañía, unificando la elaboración de folios según el Código Sustancial del Trabajo colombiano para sus departamentos de gestión humana, administración y contabilidad. Su diagramación clara, cláusulas predefinidas y papel de alta durabilidad aseguran la continuidad operativa durante los trámites institucionales, permitiendo el diligenciamiento rápido de causales, periodos de prueba y prórrogas sin demoras ni inconsistencias documentales. Incorpore este talonario a sus existencias para elevar la eficiencia logística en sus compras de papelería especializada, formas minerva y suministros de oficina, impulsando el bienestar del equipo al brindar transparencia, orden y seguridad jurídica en las relaciones laborales con sus colaboradores.', 23054.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/77568.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Contrato Minerva Compraventa Vehiculo Automotor 5508 X 12', 'contrato-minerva-compraventa-vehiculo-automotor-5508-x-12-5632', 'Contrato Compraventa Vehículo Automotor por 12 Minerva 5508 Documento formal para transacciones seguras y ordenadas de vehículos Contrato de compraventa de vehículo automotor marca Minerva 5508, presentado en formato de 12 unidades, diseñado para formalizar la transferencia de propiedad de vehículos mediante un documento estructurado y de uso legal. Su formato facilita el registro claro de las condiciones de la negociación, datos de las partes y especificaciones del vehículo, garantizando orden documental y soporte administrativo en procesos de compra y venta de uso frecuente.', 24706.00, 20, 38, true, false, 'https://www.abastece.co/abastece/images/5632.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cordon para Escarapela Color Naranja', 'cordon-para-escarapela-color-naranja-73874', 'Cordón para Escarapela Color Naranja Perfecto para Personalizar y Decorar Descubre nuestro cordón para escarapela en un vibrante color naranja. Ideal para personalizar tus escarapelas, manualidades y proyectos de decoración. Su resistencia y colorido añaden un toque especial a cualquier diseño. ¡Haz que tus creaciones destaquen con nuestro cordón de alta calidad!', 316.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/73874.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cosedora Industrial Nithan NHI-408  240 Hojas', 'cosedora-industrial-nithan-nhi-408-240-hojas-71137', 'Cosedora Industrial Nithan NHI-408 240 hojas Alto rendimiento para engrapado de grandes volúmenes documentales Cosedora industrial Nithan NHI-408 diseñada para engrapar hasta 240 hojas de forma simultánea, fabricada con estructura metálica de alta resistencia para uso intensivo en entornos administrativos y de archivo. Su sistema de presión reforzada permite un cierre firme y uniforme de los documentos, optimizando procesos de organización, consolidación de informes y manejo de expedientes voluminosos con desempeño estable y continuo.', 71968.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/71137.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cosedora Kw-trio Capacidad 210 Hojas Ref 050 LA', 'cosedora-kw-trio-capacidad-210-hojas-ref-050-la-77214', 'Cosedora KW‑TRIO Alta Capacidad 210 Hojas Ref. 050 LA · Unidad Sujeción confiable para grandes volúmenes documentales Cosedora de alta capacidad diseñada para la encuadernación segura de documentos extensos, con capacidad de grapado de hasta 210 hojas. Construida en estructura metálica robusta, ofrece estabilidad y durabilidad en uso intensivo, asegurando un desempeño consistente a lo largo del tiempo. Su sistema de palanca optimiza la aplicación de fuerza, facilitando el grapado de altos volúmenes con menor esfuerzo operativo. Referencia 050 LA de KW‑TRIO, esta cosedora se integra como un insumo estratégico para la estandarización del archivo físico, apoyando la continuidad operativa, el control documental y la eficiencia logística en entornos administrativos con alta rotación de información', 69384.00, 20, 50, true, false, 'https://www.abastece.co/abastece/images/77214.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cosedora Offi Esco Grande Metalica 20 Hoja OE-338', 'cosedora-offi-esco-grande-metalica-20-hoja-oe-338-73728', 'Cosedora Offi Esco Grande Metálica 20 Hojas OE-338 Engrapado preciso para organización documental de uso diario Cosedora grande marca Offi-Esco OE-338 fabricada en estructura metálica resistente, diseñada para engrapar hasta 20 hojas de forma simultánea. Su mecanismo de presión estable permite un cierre uniforme de los documentos, garantizando fijación segura y alineación precisa del papel. Es una herramienta funcional para tareas administrativas, organización de archivos y manejo de documentos de uso frecuente en entornos operativos.', 8120.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/73728.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cosedora Paper Pro DeskTop Para 20 Hojas', 'cosedora-paper-pro-desktop-para-20-hojas-72692', 'Cosedora Paper Pro DeskTop para 20 Hojas Engrapado eficiente para organización documental de escritorio Cosedora de escritorio Paper Pro DeskTop diseñada para engrapar hasta 20 hojas de manera simultánea, con estructura resistente que garantiza estabilidad en el uso diario. Su mecanismo de presión permite un cierre preciso y uniforme de los documentos, facilitando la organización de archivos, reportes y material administrativo, con un desempeño confiable para tareas operativas de uso frecuente en entornos de oficina.', 21756.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/72692.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cuaderno Argollado 5 Materias 85 Cuadriculado 320 Hj. Diseño Surtido.', 'cuaderno-argollado-5-materias-85-cuadriculado-320-hj-diseno-surtido-77760', 'Cuaderno Argollado 5 Materias 85 Cuadriculado 320 Hj. Diseño Surtido. ¡Organización integral por asignaturas, gran capacidad de hojas y resistencia para el día a día! Mantenga todos sus apuntes, proyectos e ideas perfectamente clasificados en un solo lugar con el cuaderno argollado de 5 materias cuadrícula 85 de 320 hojas. Equipado con separadores de materia de fácil acceso y hojas cuadriculadas de excelente gramaje, este cuaderno evita el traspaso de tinta y facilita una escritura fluida y ordenada. Su anillado doble O de alta resistencia asegura la durabilidad de la encuadernación ante el uso constante, mientras que sus carátulas de pasta dura en variados y atractivos diseños surtidos protegen el contenido contra el desgaste. Es la herramienta de estudio y trabajo indispensable para estudiantes universitarios, colegios y profesionales que requieren máxima capacidad y versatilidad en su rutina diaria. ¡Adquiera el suyo hoy y lleve su productividad al siguiente nivel!', 11172.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/77760.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cuaderno Argollado 7 Materias 105 (*) Cuadros', 'cuaderno-argollado-7-materias-105-cuadros-72595', 'Cuaderno Argollado 7 Materias 105 Organización y Comodidad para tus Tareas Académicas El Cuaderno Argollado 7 Materias 105 es la opción perfecta para estudiantes y profesionales que necesitan mantener sus notas y tareas organizadas. Con 7 materias distintas, este cuaderno permite clasificar y dividir los temas de manera eficiente, facilitando el acceso rápido a la información. Su estructura de argollas proporciona flexibilidad para agregar o quitar hojas según sea necesario, mientras que su tapa resistente protege el contenido. Ideal para uso en la escuela, universidad o trabajo, este cuaderno es la herramienta ideal para quienes buscan funcionalidad y organización en un solo producto.', 15558.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/72595.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cuaderno Argollado Pasta Dura 105 Cuadriculado Unicolor.', 'cuaderno-argollado-pasta-dura-105-cuadriculado-unicolor-77536', 'Cuaderno Argollado Pasta Dura 105 Hojas Cuadriculado Unicolor ¡Equipe a sus colaboradores con herramientas de escritura de alta durabilidad y garantice el máximo orden en su gestión diaria! Asegure una excelente presentación institucional, facilite la toma de notas en reuniones corporativas y proteja la información clave de su empresa con un insumo papatero de alta resistencia y acabados profesionales. El uso del cuaderno argollado pasta dura de 105 hojas cuadriculado unicolor facilita la estandarización de procesos administrativos y de capacitación, unificando la dotación de insumos de escritura para sus diferentes departamentos, comités o kits de ingreso de personal bajo un diseño sobrio, elegante y funcional. Su estructura con carátula rígida plastificada y anillado metálico de alta durabilidad garantiza la continuidad operativa de sus equipos de trabajo, ofreciendo una superficie de apoyo firme para uso en campo o escritorio y evitando el deterioro o pérdida de hojas durante la jornada laboral. Incorpore esta referencia a sus existencias para optimizar la eficiencia logística en sus compras de papelería y útiles de oficina, impulsando el bienestar del equipo al suministrar herramientas de calidad que proyectan profesionalismo y organización en cada tarea.', 8875.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/77536.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cuaderno Cosido Ferrocarill 100 Hojas', 'cuaderno-cosido-ferrocarill-100-hojas-74317', 'Cuaderno Cosido Ferrocarril - 100 Hojas ¡El aliado perfecto para el perfeccionamiento de la caligrafía y la escritura! El Cuaderno de Rayado Ferrocarril es la herramienta pedagógica esencial para el desarrollo de la escritura legible y el manejo del renglón. Su encuadernación cosida de alta resistencia evita el desprendimiento de las hojas, garantizando una larga vida útil durante el año escolar. Gracias a su rayado especial con guías visuales, facilita la correcta proporción de las letras y el orden en los textos. Es el insumo indispensable para estudiantes en etapa de aprendizaje, talleres de caligrafía, educación primaria y procesos de nivelación académica.', 2470.00, 20, 43, true, false, 'https://www.abastece.co/abastece/images/74317.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cubierta Legajadora Desacificada Oficio De300g.  Ref. 502367', 'cubierta-legajadora-desacificada-oficio-de300g-ref-502367-70204', 'Cubierta Legajadora Desacidificada Oficio de 300 g Ref. 502367 Protección documental para archivo seguro y conservación prolongada Cubierta legajadora tamaño oficio fabricada en cartulina desacidificada de 300 g, referencia 502367, diseñada para el resguardo y organización de documentos en procesos de archivo físico. Su composición libre de ácido contribuye a la preservación del papel, reduciendo el deterioro con el tiempo, mientras su resistencia estructural permite una sujeción firme del contenido, facilitando la clasificación y almacenamiento ordenado en entornos administrativos de uso continuo.', 3708.00, 20, 48, true, false, 'https://www.abastece.co/abastece/images/70204.jpg'),
('c3333333-3333-3333-3333-333333333333', 'cuchilla bisturi olfa pequeña (negra) ref: ABB-10B', 'cuchilla-bisturi-olfa-pequena-negra-ref-abb-10b-9487', 'Cuchilla Bisturí Olfa Pequeña (Negra) – Ref: ABB-10B Precisión y cortes perfectos para tus proyectos más detallados La Cuchilla Bisturí Olfa Pequeña (Negra), con referencia ABB-10B, está diseñada para ofrecer una precisión excepcional en cada corte. Ideal para trabajos de arte, manualidades, modelismo y diseño, su afilada cuchilla garantiza cortes nítidos y controlados en materiales como papel, cartón, plástico y más. Con un diseño compacto y ergonómico, esta cuchilla te brinda la comodidad que necesitas para realizar tus proyectos con exactitud. ¡Obtén resultados profesionales con Olfa en cada detalle!', 16481.00, 20, 53, true, false, 'https://www.abastece.co/abastece/images/9487.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cuchilla Stanley X5u. Ref:11-921', 'cuchilla-stanley-x5u-ref11-921-70721', 'Cuchilla Stanley x5u. Ref: 11-921: Precision y Durabilidad en tus Proyectos 5 Unidades para un Corte Eficiente y Seguro La Cuchilla Stanley x5u. Ref: 11-921 es la herramienta perfecta para quienes buscan precision y fiabilidad en sus cortes. Con un diseño afilado y robusto, estas cuchillas son ideales para una variedad de materiales, desde carton hasta plasticos. Cada paquete incluye 5 unidades, asegurando que siempre tengas un corte limpio y eficiente a mano. ¡Mejora tu caja de herramientas con la calidad de Stanley y lleva tus proyectos al siguiente nivel!', 9628.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/70721.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Cuenta Hilos Lupa 5 X', 'cuenta-hilos-lupa-5-x-76567', 'Cuenta Hilos Lupa 5X Precisión visual para control y verificación de detalles textiles Cuenta hilos tipo lupa con aumento de 5X, diseñada para la inspección detallada de tejidos, bordados y superficies textiles. Su lente de aumento permite una visualización clara de la trama y el conteo preciso de hilos, facilitando procesos de control de calidad, verificación de patrones y análisis técnico en entornos industriales o de confección, con un diseño compacto que favorece su uso continuo y portátil.', 39430.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/76567.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Destructora De Documentos Ref: P30C Fellowes 6 Hojas Particulas', 'destructora-de-documentos-ref-p30c-fellowes-6-hojas-particulas-3785', 'Destructora de Documentos Ref: P-30C Fellowes 6 hojas Partículas Seguridad documental compacta para eliminación eficiente de información sensible Destructora de documentos Fellowes P-30C diseñada para triturar hasta 6 hojas simultáneamente en corte tipo partículas, reduciendo el papel a fragmentos pequeños que aumentan el nivel de seguridad en la disposición de información confidencial. Su sistema de corte cruzado permite una destrucción uniforme de documentos, facilitando la gestión segura de archivos obsoletos en entornos administrativos de uso continuo y controlado.', 36826.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/3785.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Destructora Pelikan CD x10', 'destructora-pelikan-cd-x10-75059', 'Destructora de Documentos Pelikan X10 CD ¡Seguridad de alto nivel y versatilidad para la eliminación de información sensible! La Destructora Pelikan X10 CD es una solución integral para la protección de datos en entornos domésticos y de oficina. Este equipo de alto rendimiento tiene capacidad para destruir hasta 10 hojas simultáneamente en micropartículas, garantizando un nivel de seguridad óptimo para documentos confidenciales. Además, cuenta con una ranura independiente diseñada específicamente para la destrucción de CDs, DVDs y tarjetas de crédito, gestionando los residuos de forma eficiente. Su diseño compacto incluye funciones de retroceso automático y protección contra sobrecalentamiento. Es el insumo indispensable para departamentos de recursos humanos, oficinas contables, entidades financieras y uso personal preventivo.', 391826.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/75059.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Destructora Pelikan CD x18', 'destructora-pelikan-cd-x18-77219', 'Destructora X18 CD Pelikan · Unidad Protección de información con destrucción segura y continua Destructora de documentos diseñada para la eliminación segura de información sensible, con capacidad de corte X18 CD que permite triturar papel, tarjetas y discos compactos en fragmentos uniformes. Fabricada por Pelikan, integra un sistema de alimentación estable para un desempeño constante en jornadas de uso recurrente. Su formato compacto facilita la ubicación en áreas administrativas, mientras su operación eficiente apoya la estandarización de protocolos de seguridad documental. Este insumo estratégico contribuye a la continuidad operativa al reducir riesgos asociados a la gestión de información, optimizar tiempos de destrucción y mantener un entorno ordenado y confiable desde una perspectiva logística y de control.', 858985.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/77219.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Dispensador Con 5 Cuchillas Truper Ref 16953', 'dispensador-con-5-cuchillas-truper-ref-16953-74941', 'Dispensador con 5 Cuchillas Truper (Ref: 16953) ¡Resistencia industrial y seguridad en el almacenamiento para cortes de alta exigencia! El Dispensador de Cuchillas Truper Ref: 16953 ofrece una solución eficiente y segura para el reemplazo de hojas en bisturís de alta resistencia (Utility Knives). Fabricadas en acero SK5, estas cuchillas son dos veces más resistentes al desgaste que las convencionales, permitiendo cortes precisos en materiales densos como Drywall, caucho, cuero y plásticos. El dispensador plástico protege al usuario de cortes accidentales durante la manipulación y mantiene el filo de las hojas intacto hasta su uso. Es el insumo indispensable para contratistas, talleres de mantenimiento, proyectos de construcción y bodegas de logística.', 3954.00, 20, 52, true, false, 'https://www.abastece.co/abastece/images/74941.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Dispensador De Cinta De Empaque Manual 48 Mm', 'dispensador-de-cinta-de-empaque-manual-48-mm-76057', 'Dispensador de Cinta de Empaque Manual 48 mm Aplicación rápida y eficiente para sellado continuo de embalajes Dispensador manual para cinta de empaque compatible con rollos de 48 mm, diseñado para agilizar el cerrado de cajas y paquetes en procesos logísticos y de almacenamiento. Su estructura ergonómica permite un corte preciso y una aplicación uniforme de la cinta, optimizando la velocidad de embalaje y reduciendo el desperdicio de material, con un desempeño estable en operaciones de uso frecuente y continuo.', 22638.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/76057.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Dispensador Metalico De Pelicula Stretch Rollo Ancho', 'dispensador-metalico-de-pelicula-stretch-rollo-ancho-75558', 'Dispensador Metálico de Película Stretch Rollo Ancho Control eficiente para embalaje seguro y uniforme de cargas Dispensador metálico para película stretch de rollo ancho, diseñado para facilitar la aplicación manual de film estirable en procesos de embalaje y paletizado. Su estructura resistente garantiza estabilidad durante el uso, permitiendo un tensado uniforme del material para asegurar la fijación y protección de cargas. Es una herramienta funcional para operaciones logísticas, almacenamiento y distribución que requieren continuidad operativa y eficiencia en el empaque.', 179987.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/75558.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Dispensador Para Cinta 1 Pulgada  (2,54 Cm).', 'dispensador-para-cinta-1-pulgada-254-cm-77665', 'Dispensador Para Cinta 1 Pulgada (2,54 cm) ¡Agilice sus labores de empaque, selle con precisión y evite el desperdicio de cinta! Optimice sus tareas de embalaje, marcado o manualidades con este práctico dispensador para cintas de 1 pulgada (2,54 cm) de ancho. Equipado con una cuchilla dentada de corte limpio y una estructura resistente de fácil agarre, facilita la aplicación continua y rápida en cajas o superficies sin complicaciones. ¡Cómpralo hoy y mantén tus herramientas de trabajo ordenadas y eficientes!', 7791.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/77665.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Escarapela  17 X 12 Cms Calibre 4', 'escarapela-17-x-12-cms-calibre-4-9572', 'Escarapela 17 x 12 cms Calibre 4 Identificación visible y funcional para control de acceso y organización Escarapela en formato 17 x 12 cm con calibre 4, fabricada en material plástico transparente de alta resistencia, diseñada para la presentación de credenciales, carnés o identificaciones. Su tamaño amplio permite una visualización clara del contenido, mientras su grosor proporciona rigidez y durabilidad, facilitando el uso en procesos de identificación, control de acceso y organización operativa en entornos administrativos y corporativos de uso continuo.', 294.00, 20, 51, true, false, 'https://www.abastece.co/abastece/images/9572.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Escarapela De Vinilo Para Carnet Vertical 9x6 Cms Calibre 6', 'escarapela-de-vinilo-para-carnet-vertical-9x6-cms-calibre-6-3455', 'Escarapela de Vinilo para Carnet Vertical (9x6 cm) - Calibre 6 ¡Protección de alta transparencia y durabilidad para identificación institucional! La Escarapela de Vinilo en formato vertical es la solución estándar para la protección y exhibición de documentos de identidad, carnets corporativos y pases de eventos. Fabricada en vinilo flexible de calibre 6, ofrece una resistencia superior contra el roce, la humedad y el desgaste diario, manteniendo la legibilidad del documento intacta. Su diseño incluye una perforación universal en la parte superior para ser utilizada con cintas (reatas), ganchos o yoyos. Con unas dimensiones de 9x6 cm, es el insumo indispensable para ferias y congresos, departamentos de seguridad, instituciones educativas y control de acceso en empresas.', 188.00, 20, 32, true, false, 'https://www.abastece.co/abastece/images/3455.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Escarapela Para Cedula C-5  X100 Und. (9.7x6.5 Cms)', 'escarapela-para-cedula-c-5-x100-und-97x65-cms-73879', 'Escarapela para Cédula C-5 x100 und. (9.7 x 6.5 cms) Protección compacta para identificación segura y visible Escarapelas formato C-5 en tamaño 9.7 x 6.5 cm, presentadas en paquete de 100 unidades, fabricadas en material plástico transparente de alta resistencia, diseñadas para la protección y exhibición de documentos de identificación como cédulas o carnés. Su formato compacto facilita el porte seguro y la visualización clara de la información, optimizando procesos de control de acceso, registro y organización en entornos administrativos y operativos de uso continuo.', 18879.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/73879.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Escarcha En Libra Dorada', 'escarcha-en-libra-dorada-77819', 'Escarcha En Libra Dorada ¡Partículas de alto brillo, pigmentación metálica uniforme y formato a granel de 500g para producción de artes gráficas y escolar! Maximice el rendimiento en proyectos decorativos, piñatería, producción litográfica y manualidades a gran escala con la escarcha (brillantina / glitter) en presentación de una libra (500 gramos) en color dorado. Compuesta por micropartículas copolimerizadas de corte uniforme con acabado metálico de alta reflectividad, esta purpurina ofrece un brillo intenso y homogéneo al ser fijada sobre papel, cartón, madera, icopor, textiles o resinas con adhesivos vinílicos y líquidos. Su formato a granel de 500 g optimiza los costos por gramo en talleres de diseño, industrias publicitarias, confección de temporada navideña, centros educativos y papelerías mayoristas. Es un insumo de alta rotación e indispensable para material P.O.P., escenografía, tarjetas de eventos, arreglos florales y proyectos de artes manuales. ¡Incorpore este insumo a sus compras al por mayor y garantice acabados luminosos de alta definición!', 10584.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/77819.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Escarcha En Tubo Colores Surtidos Por Unidad', 'escarcha-en-tubo-colores-surtidos-por-unidad-1145', 'Escarcha en Tubo – Colores Surtidos por Unidad Brilla y decora con los colores vibrantes de nuestra escarcha La Escarcha en Tubo, disponible en colores surtidos por unidad, es perfecta para darle un toque de brillo y creatividad a tus manualidades, proyectos escolares o decoraciones festivas. Fácil de aplicar y con colores brillantes, esta escarcha es ideal para hacer que tus trabajos resalten con un acabado espectacular. ¡Haz brillar tu imaginación con la escarcha más divertida y colorida!', 187.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/1145.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Esfero Offi Esco OE 077F Caja X12 Cafe Semi Gel  0.7 Tapa', 'esfero-offi-esco-oe-077f-caja-x12-cafe-semi-gel-07-tapa-74991', 'Esfero Offi-Esco OE-077F Caja x12 Café Semi Gel 0.7 Tapa Escritura fluida con acabado profesional para uso continuo Esfero Offi-Esco OE-077F en tinta color café semi gel con punta de 0.7 mm, presentado en caja de 12 unidades con sistema de tapa protectora. Diseñado para ofrecer una escritura suave, constante y de secado uniforme, permitiendo trazos definidos en documentos, registros y formularios. Su formato semi gel mejora la fluidez del trazo sin sacrificar control, optimizando el desempeño en tareas administrativas y operativas de uso frecuente.', 4716.00, 20, 23, true, false, 'https://www.abastece.co/abastece/images/74991.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Esfero Offi Esco OE 077F Caja X12 Fucsia Semi Gel  0.7 Tapa', 'esfero-offi-esco-oe-077f-caja-x12-fucsia-semi-gel-07-tapa-74797', 'Esfero Offi-Esco OE-077F Caja x12 Fucsia Semi-Gel 0.7 Tapa ¡Optimice sus procesos de marcación y resalte la información clave con trazos suaves y vibrantes! Maximice la claridad visual y la organización de sus apuntes, revisiones de calidad y tareas administrativas con este set de escritura de alta fluidez. La presentación de este esfero Offi-Esco OE-077F caja x12 fucsia semi-gel 0.7 tapa facilita la estandarización de procesos de archivo y auditoría en la oficina, unificando los códigos de color bajo un estándar de trazo fino y secado rápido. Su tinta base semi-gel asegura la continuidad operativa en las jornadas de rotulado o corrección de documentos, garantizando un rendimiento constante y un deslizamiento homogéneo que evita manchas o interrupciones en el papel. Incorpore este suministro hoy mismo para mejorar la eficiencia logística de sus compras de papelería corporativa con un empaque institucional de alta rotación, potenciando el bienestar del equipo al proveer herramientas ergonómicas y dinámicas que reducen la fatiga al escribir y dinamizan la productividad diaria.', 4714.00, 20, 33, true, false, 'https://www.abastece.co/abastece/images/74797.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Esfero Offi Esco OE 077F Caja X12 Morado Semi Gel 0.7 Tapa', 'esfero-offi-esco-oe-077f-caja-x12-morado-semi-gel-07-tapa-77449', 'Esfero Offi-Esco OE-077F Caja x12 Morado Semi-Gel 0.7 Tapa ¡Optimice sus procesos de revisión y organice la información clave con trazos suaves y fluidos! Maximice la claridad visual y la clasificación de sus notas, revisiones de calidad, firmas o codificación de documentos con este set de escritura de alta fluidez. La presentación de este esfero Offi-Esco OE-077F caja x12 morado semi-gel 0.7 tapa facilita la estandarización de procesos de archivo y control en la oficina, unificando los códigos de color bajo un estándar de trazo fino y secado rápido. Su tinta base semi-gel asegura la continuidad operativa en las jornadas de rotulado o corrección, garantizando un rendimiento constante y un deslizamiento homogéneo que evita manchas en el papel. Incorpore este suministro hoy mismo para mejorar la eficiencia logística de sus compras de papelería corporativa con un empaque institucional de alta rotación, potenciando el bienestar del equipo al proveer herramientas ergonómicas que reducen la fatiga al escribir y dinamizan la productividad diaria.', 4714.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/77449.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Esfero Offi Esco OE 077F Caja X12 Verde Claro Semi Gel 0.7 Tapa', 'esfero-offi-esco-oe-077f-caja-x12-verde-claro-semi-gel-07-tapa-77448', 'Esfero Offi-Esco OE-077F Caja x12 Verde Claro Semi-Gel 0.7 Tapa ¡Optimice sus procesos de auditoría y resalte la información clave con trazos suaves y nítidos! Maximice la claridad visual y la organización de sus apuntes, revisiones de calidad, firmas o codificación de documentos con este set de escritura de alta fluidez. La presentación de este esfero Offi-Esco OE-077F caja x12 verde claro semi-gel 0.7 tapa facilita la estandarización de procesos de archivo y control en la oficina, unificando los códigos de color bajo un estándar de trazo fino y secado rápido. Su tinta base semi-gel asegura la continuidad operativa en las jornadas de rotulado o corrección, garantizando un rendimiento constante y un deslizamiento homogéneo que evita manchas en el papel. Incorpore este suministro hoy mismo para mejorar la eficiencia logística de sus compras de papelería corporativa con un empaque institucional de alta rotación, potenciando el bienestar del equipo al proveer herramientas ergonómicas que reducen la fatiga al escribir y dinamizan la productividad diaria.', 5337.00, 20, 18, true, false, 'https://www.abastece.co/abastece/images/77448.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Esfero Offi-Esco OE-076F Semi Gel Rojo 0.7 Tapa', 'esfero-offi-esco-oe-076f-semi-gel-rojo-07-tapa-71369', 'Esfero Offi-Esco OE-076F/077F Semi Gel Rojo 0.7 – Con Tapa Escritura precisa y fluida en color rojo con tinta semi-gel El Esfero Offi-Esco OE-076F/077F Semi Gel Rojo 0.7 con Tapa es perfecto para quienes necesitan un trazo nítido y sin manchas. Su tinta semi-gel ofrece una experiencia de escritura suave y fluida, ideal para tareas de subrayado, anotaciones o trabajos que requieren detalles en color rojo. El diseño con tapa asegura que el esfero esté protegido y listo para usar cuando lo necesites. Con un tamaño de punta de 0.7 mm, ofrece precisión en cada línea. ¡Añade un toque de color y profesionalismo a tu escritura con el esfero Offi-Esco!', 394.00, 20, 29, true, false, 'https://www.abastece.co/abastece/images/71369.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Espiral Plastico 11 Mm Para 80 Hjs Paq X 10 Mt', 'espiral-plastico-11-mm-para-80-hjs-paq-x-10-mt-77124', 'Espiral Plástico 11 mm para 80 Hojas Paq x 10 m Encuadernación flexible para organización documental continua Espiral plástico de 11 mm diseñado para encuadernar hasta 80 hojas, presentado en rollo de 10 metros, ideal para sistemas de organización documental manual. Su material flexible permite un ajuste preciso al perforado, facilitando la rotación de páginas y manteniendo una sujeción estable, optimizando la presentación de informes, cuadernos y material administrativo de uso frecuente en entornos operativos.', 28989.00, 20, 47, true, false, 'https://www.abastece.co/abastece/images/77124.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Espiral Plastico 14 Mm Para 120 Hjs Paq X 10 Mt', 'espiral-plastico-14-mm-para-120-hjs-paq-x-10-mt-77125', 'Espiral Plástico 14 mm para 120 Hojas Paq x 10 m Mayor capacidad de encuadernación para documentos de uso continuo Espiral plástico de 14 mm diseñado para encuadernar hasta 120 hojas, presentado en rollo de 10 metros, ideal para sistemas de organización documental que requieren mayor volumen de almacenamiento. Su material flexible facilita el ajuste al perforado y permite una rotación fluida de las páginas, garantizando una sujeción estable y una presentación ordenada de informes, manuales y documentos administrativos en entornos operativos de uso frecuente.', 38279.00, 20, 50, true, false, 'https://www.abastece.co/abastece/images/77125.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Espiral Plastico 8 Mm Para 50 Hjs Paq X 20 Mt', 'espiral-plastico-8-mm-para-50-hjs-paq-x-20-mt-77123', 'Espiral Plástico 8 mm para 50 Hojas Paq x 20 m Encuadernación ligera para organización ágil de documentos Espiral plástico de 8 mm diseñado para encuadernar hasta 50 hojas, presentado en rollo de 20 metros, ideal para la organización de documentos de bajo volumen. Su material flexible permite un ajuste preciso al perforado, facilitando la rotación de páginas y manteniendo una sujeción estable, optimizando la presentación de informes, apuntes y material administrativo en procesos de uso frecuente y continuo.', 34222.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/77123.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Esquinero De Carton Para Embalaje  120x4x4cms.', 'esquinero-de-carton-para-embalaje-120x4x4cms-77655', 'Esquinero De Cartón Para Embalaje 120x4x4cms ¡Proteja sus cargas, asegure la estabilidad de sus estibas y evite daños en el transporte! Garantice la máxima protección de sus productos durante el almacenamiento y transporte con estos esquineros de cartón de 120 cm de largo y alas de 4x4 cm. Diseñados para reforzar las esquinas de cajas y estibas, reducen el riesgo de deformación por zunchado y mejoran la resistencia al apilamiento. ¡Adquiéralos ahora y asegure su mercancía con la mejor calidad!', 3646.00, 20, 38, true, false, 'https://www.abastece.co/abastece/images/77655.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Estuche De Carton Cilindrico Con 12 Colores Y Tajalapiz Plastico', 'estuche-de-carton-cilindrico-con-12-colores-y-tajalapiz-plastico-74893', 'Cilindro de colores(Estuche en carton cilindrico que contiene 12 colores de madera y tapa con tajalapiz. Material: Papel + ABS. Medidas: DiÃƒ¡metro 3.5 x 10.5cm de largo.', 8820.00, 20, 20, true, false, 'https://www.abastece.co/abastece/images/74893.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Estuche Organizador Para Baterias / Pilas AA Y AAA/AA01', 'estuche-organizador-para-baterias-pilas-aa-y-aaaaa01-75233', 'Estuche Organizador para Baterías / Pilas AA y AAA / AA01 Almacenamiento seguro para control y orden de pilas de uso frecuente Estuche organizador modelo AA01 diseñado para el almacenamiento y transporte de baterías tipo AA y AAA, fabricado en material resistente que protege las pilas contra golpes, humedad y desorden. Su diseño interno permite una distribución ordenada de las unidades, facilitando la identificación y acceso rápido, optimizando la gestión de insumos energéticos en entornos de oficina, mantenimiento o uso operativo continuo.', 8820.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/75233.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Etiqueta Autoadhesivas 13x13x840u. (rotulo) Fucsia', 'etiqueta-autoadhesivas-13x13x840u-rotulo-fucsia-70938', 'Etiqueta Autoadhesiva 13 x 13 mm Fucsia - Paquete x 840 Unidades ¡Identificación visual inmediata y alta densidad para control de inventarios! La Etiqueta Autoadhesiva Cuadrada de 13 x 13 mm en color fucsia es una herramienta de señalización crítica para procesos de clasificación rápida. Su color vibrante de alta visibilidad permite una identificación inmediata a distancia, facilitando la categorización de productos, estados de control de calidad o priorización de tareas. Con un adhesivo de gran estabilidad, estas etiquetas se fijan firmemente en superficies pequeñas sin levantarse. El paquete de 840 unidades garantiza un suministro duradero para operaciones de alto volumen. Es el insumo indispensable para procesos de auditoría, control de calidad (aprobados/rechazados), codificación de precios y organización de archivos por color.', 1730.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/70938.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Etiqueta Termica Directa De 100 X 30mm X 1000 Uds', 'etiqueta-termica-directa-de-100-x-30mm-x-1000-uds-72083', 'Etiqueta Térmica Directa 100 x 30 mm x 1000 Uds Identificación rápida y eficiente para procesos logísticos continuos Etiquetas térmicas directas en formato 100 x 30 mm, presentadas en rollo de 1000 unidades, diseñadas para impresión sin ribbon mediante tecnología de transferencia térmica directa. Ofrecen impresión clara y de secado inmediato, permitiendo la codificación de información variable como códigos de barras, referencias y datos logísticos. Son ideales para procesos de etiquetado en inventario, despacho y control operativo de uso continuo.', 17680.00, 20, 18, true, false, 'https://www.abastece.co/abastece/images/72083.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Etiqueta Transferencia Termica 70MM X 35mm Rollo X1.500 Etiquetas', 'etiqueta-transferencia-termica-70mm-x-35mm-rollo-x1500-etiquetas-77584', 'Etiqueta Transferencia Termica 70MM X 35mm Rollo X1.500 Etiquetas ¡Asegure la trazabilidad de sus despachos, mantenga la claridad de sus códigos de barras y optimice la gestión de inventarios! Garantice la identificación precisa de empaques, productos y lotes de distribución, evite pérdidas de información durante la cadena de transporte y mantenga lecturas óptimas mediante códigos de barras e información variable de alta resolución. El uso de la etiqueta transferencia termica 70mm x 35mm rollo x1.500 etiquetas facilita la estandarización de procesos de etiquetado, codificación e inventario en la compañía, unificando el formato de identificación para sus departamentos de logística, bodega, despachos y despacho e-commerce. Su papel adhesivo de alta adherencia y compatibilidad con cinta ribbon asegura la continuidad operativa en el centro de acopio, permitiendo una impresión fluida, secado inmediato y resistencia contra el roce o variaciones de temperatura sin desprendimientos. Incorpore este rollo a sus existencias para elevar la eficiencia logística en sus compras de insumos para etiquetado e impresoras industriales, impulsando el bienestar del equipo al suministrar herramientas confiables que facilitan las tareas de rotulación y picking de mercancía.', 15718.00, 20, 34, true, false, 'https://www.abastece.co/abastece/images/77584.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Etiquetadora Motex 6600 8 Digitos', 'etiquetadora-motex-6600-8-digitos-71194', 'Etiquetadora Motex 6600 8 Dígitos Marcación ágil y precisa para control de precios y codificación Etiquetadora manual Motex 6600 de 8 dígitos, diseñada para la impresión rápida de códigos numéricos en etiquetas autoadhesivas. Su mecanismo de rodillos permite una marcación clara y uniforme, facilitando el etiquetado de precios, lotes o referencias en procesos comerciales y logísticos. Es una herramienta funcional para operaciones de alta rotación que requieren identificación constante y manejo eficiente de productos.', 213091.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/71194.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Expositor Acrilico Classic Acrimet', 'expositor-acrilico-classic-acrimet-75176', 'Expositor Acrílico Classic Acrimet Presentación profesional para información visible y organizada Expositor en acrílico transparente modelo Classic Acrimet, diseñado para la presentación de documentos, avisos, folletos o material informativo en formato vertical u horizontal según configuración. Su estructura rígida de alta transparencia permite una visualización clara del contenido, aportando orden y profesionalismo en espacios de atención, recepción o puntos de información, con un diseño funcional para uso continuo en entornos administrativos y comerciales.', 39430.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/75176.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Ficha Bibliografica Blanca 10x14 Paquete X50u.', 'ficha-bibliografica-blanca-10x14-paquete-x50u-74226', 'Ficha Bibliográfica Blanca 10x15 Paquete x50u Registro ordenado de información para clasificación documental eficiente Fichas bibliográficas en color blanco con formato 10 x 15 cm, presentadas en paquete de 50 unidades, fabricadas en papel de buena rigidez que permite escritura clara y ordenada. Diseñadas para el registro, clasificación y organización de información en sistemas de archivo manual, facilitan la gestión de datos bibliográficos, inventarios o referencias, manteniendo un uso funcional en procesos académicos y administrativos de uso continuo.', 864.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/74226.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Fichas Bibliograficas 10x14 Rosadas Paquete X100u.', 'fichas-bibliograficas-10x14-rosadas-paquete-x100u-73700', 'Fichas Bibliográficas Rosadas - 10 x 14 cm (Paquete x 100 Unidades) ¡Organiza tus ideas y estudios con un toque de color y estilo! El Paquete de Fichas Bibliográficas Rosadas es la herramienta ideal para estudiantes, investigadores y profesionales que buscan un método de organización visualmente distintivo y eficiente. Con un tamaño de 10 x 14 cm, estas tarjetas ofrecen el espacio perfecto para resumir conceptos, crear bancos de preguntas (flashcards), tomar apuntes de referencia o catalogar información importante. Su color rosado vibrante facilita la clasificación por temas o categorías, permitiendo una rápida identificación visual en tu escritorio o archivador. Fabricadas con cartulina de alta calidad y gramaje adecuado, garantizan una escritura fluida con diversos tipos de tintas sin traspasar el papel, asegurando durabilidad y orden en todos tus proyectos académicos o laborales.', 1614.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/73700.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Flechadora (Pistola) Avery Dennison Pesada', 'flechadora-pistola-avery-dennison-pesada-76489', 'Flechadora (Pistola) Avery Dennison - Serie Pesada (Heavy Duty) ¡Resistencia industrial para el etiquetado de materiales exigentes! La Pistola Flechadora Avery Dennison de Trabajo Pesado es la herramienta líder en la industria para la fijación de etiquetas en materiales gruesos o densos como mezclilla (denim), lona, cuero, alfombras y textiles industriales. Diseñada para soportar un uso intensivo y continuo, esta flechadora cuenta con un mecanismo interno reforzado y una aguja de acero de alta penetración que atraviesa las fibras sin causar desgarres innecesarios. Su diseño ergonómico reduce la fatiga del operario durante jornadas largas, garantizando una aplicación rápida y segura de sujetadores (flechas). Es la opción preferida por fabricantes y centros de distribución que exigen máxima durabilidad, precisión y un rendimiento superior en entornos de producción de alto volumen.', 86966.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/76489.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Foamy Escarchado Azul Oscuro 1/8 Por 10 Und', 'foamy-escarchado-azul-oscuro-18-por-10-und-77668', 'Foamy Escarchado Azul Oscuro 1/8 Por 10 Und ¡Añada un toque deslumbrante, brillo vibrante y textura a todas sus manualidades y proyectos! Haga destacar sus creaciones con este paquete de 10 pliegos de foamy escarchado octavo (1/8) en un elegante color azul oscuro. Su acabado brillante de alta calidad es ideal para maquetas, decoraciones festivas, proyectos escolares, disfraces y trabajos de tarjetería, ofreciendo un material fácil de recortar, moldear y pegar. ¡Adquiéralo hoy mismo y déle vida a sus ideas con la mayor vistosidad!', 5202.00, 20, 48, true, false, 'https://www.abastece.co/abastece/images/77668.jpg')
INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c3333333-3333-3333-3333-333333333333', 'Foamy Escarchado Negro 1/8 Paq.x.10u.', 'foamy-escarchado-negro-18-paqx10u-73919', 'Foamy Escarchado Negro - Octavo (1/8) Paquete x 10 Unidades ¡Elegancia y contraste brillante para decoraciones y proyectos de diseño! El Foamy (Goma EVA) Escarchado en color Negro es un material premium diseñado para aportar sobriedad y un contraste visual único gracias a su acabado con brillo intenso. Su superficie está recubierta con escarcha de alta densidad que captura la luz, ideal para resaltar figuras y fondos en trabajos manuales. Con un tamaño de un octavo (1/8) por lámina, ofrece la flexibilidad necesaria para ser cortado, pegado o termoformado sin perder su estructura. Es el insumo indispensable para manualidades de gala, decoraciones temáticas, escenografías, elaboración de disfraces y proyectos artísticos de alto nivel.', 4727.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/73919.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Foamy Lamina Pliego 1.8 Mm Blanco Paq.x 10u.', 'foamy-lamina-pliego-18-mm-blanco-paqx-10u-73305', 'Foamy en Lámina Tamaño Pliego - 1.8 mm Blanco (Paquete x 10 Unidades) ¡La base perfecta y versátil para tus proyectos creativos a gran escala! El Paquete de Foamy (Goma Eva) en Lámina Pliego es el insumo indispensable para manualistas, escenógrafos y docentes que requieren calidad y amplitud en sus creaciones. Con un espesor de 1.8 mm, estas láminas ofrecen el equilibrio ideal entre flexibilidad y resistencia, permitiendo ser cortadas, pegadas, termoformadas o pintadas con total facilidad. Su color blanco puro proporciona una base neutra excelente para resaltar otros colores o para ser decorada con marcadores, escarcha y pinturas acrílicas. Gracias a su generoso tamaño pliego y su presentación de 10 unidades, es la opción más eficiente para la elaboración de disfraces, carteleras, material didáctico o decoraciones de eventos que exigen un acabado uniforme y profesional.', 22700.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/73305.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Foamy Lamina Pliego 1.8 Mm Negro Paquete Por 10 Unidades', 'foamy-lamina-pliego-18-mm-negro-paquete-por-10-unidades-73306', 'Foamy en Lámina Tamaño Pliego - 1.8 mm Negro (Paquete x 10 Unidades) ¡Profundidad y elegancia para manualidades y proyectos profesionales! El Paquete de Foamy (Goma Eva) Negro en tamaño Pliego es la solución perfecta para quienes buscan un material de gran formato con un acabado sobrio y versátil. Con un espesor de 1.8 mm, estas láminas ofrecen una textura suave y flexible que facilita el corte preciso, el pegado y el termoformado, permitiendo crear figuras con volumen o bases estructurales resistentes. El color negro intenso es ideal para la elaboración de escenografías, disfraces, manualidades de Halloween, plantillas industriales o material didáctico que requiera contraste. Al venir en un práctico paquete de 10 unidades, garantiza el suministro necesario para proyectos extensos o producciones en serie, manteniendo siempre un acabado uniforme y de alta calidad.', 23920.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/73306.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Foamy Moldeable Klipp X6 Unidades', 'foamy-moldeable-klipp-x6-unidades-74716', 'Foamy Moldeable Klipp - Paquete x 6 Unidades (Colores Surtidos) ¡Despierta la creatividad con texturas suaves y colores vibrantes! El Foamy Moldeable Klipp es el material revolucionario diseñado para que niños y artistas den vida a sus ideas de forma limpia y divertida. Este paquete de 6 unidades ofrece una textura suave, elástica y extremadamente liviana, que no mancha las manos ni deja residuos pegajosos. Gracias a su fórmula innovadora, las piezas modeladas se secan al aire a temperatura ambiente, adquiriendo una consistencia firme y esponjosa similar al foamy tradicional sin necesidad de horneado. Sus colores son mezclables entre sí, permitiendo crear una gama infinita de matices para figuras en 3D, apliques decorativos o proyectos escolares. Es la herramienta perfecta para desarrollar la motricidad fina y la expresión artística de manera segura y profesional.', 2640.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/74716.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Foamy Moldeable X4 Unidades', 'foamy-moldeable-x4-unidades-74225', 'Foamy Moldeable - Paquete x 4 Unidades (Colores Surtidos) ¡Crea figuras increíbles con una textura ligera y secado rápido! El Foamy Moldeable de 4 unidades es el material ideal para pequeños artistas y entusiastas de las manualidades que buscan una experiencia de modelado limpia y divertida. Su textura extremadamente suave y elástica permite dar forma a figuras con gran detalle sin que se pegue a las manos ni a las superficies. Lo mejor de este material es que seca al aire, endureciéndose ligeramente para conservar tus creaciones de forma permanente sin necesidad de hornear. Las 4 barras de colores vibrantes pueden mezclarse entre sí para obtener nuevos tonos, lo que lo hace perfecto para proyectos escolares, decoración de lapiceros o la creación de personajes en 3D con un acabado liso y profesional.', 10257.00, 20, 42, true, false, 'https://www.abastece.co/abastece/images/74225.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Folder 4 Divisiones Con Aletas Impresas A Una Tinta', 'folder-4-divisiones-con-aletas-impresas-a-una-tinta-72641', 'Folder de 4 Divisiones con Aletas - Impresión a Una Tinta ¡Organización especializada y profesional para tu gestión documental! El Folder de 4 Divisiones con Aletas es la solución definitiva para el manejo de expedientes complejos que requieren una clasificación interna rigurosa. Fabricado en cartulina de alto gramaje para garantizar durabilidad y protección, este folder cuenta con divisiones integradas que permiten separar documentos por categorías, fechas o procesos dentro de una misma carpeta. Su diseño incluye aletas laterales que aseguran el contenido y evitan la caída accidental de hojas, mientras que su impresión a una tinta permite personalizar campos de identificación, logos o tablas de control de manera sobria y profesional. Ideal para historias clínicas, archivos notariales, expedientes jurídicos o procesos de recursos humanos que exigen orden y una presentación impecable.', 8240.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/72641.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Folder Plastico Oficio Con Gancho Azul', 'folder-plastico-oficio-con-gancho-azul-70648', 'Folder Plástico Oficio con Gancho Azul: Organización y Protección para tus Documentos Folder Resistente con Gancho para Archivar Documentos de Tamaño Oficio El **Folder Plástico Oficio con Gancho Azul** es la solución ideal para mantener tus documentos organizados y protegidos. Fabricado en plástico resistente, este folder de tamaño oficio ofrece un diseño práctico con gancho para asegurar tus papeles de manera ordenada y segura. Su color azul le da un toque profesional, mientras que su material duradero garantiza una larga vida útil. Perfecto para oficinas, escuelas o el hogar, este folder es ideal para archivar documentos importantes, contratos y más.', 1548.00, 20, 30, true, false, 'https://www.abastece.co/abastece/images/70648.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Forma Continua 9 1/2  X 11 3 Partes Blanca', 'forma-continua-9-12-x-11-3-partes-blanca-76058', 'Forma Continua 9 1/2&quot; x 11&quot; - 3 Partes (Blanca/Blanca/Blanca) ¡Optimiza tu facturación masiva con copias instantáneas de alta legibilidad! La Forma Continua de 9 1/2 x 11 pulgadas en 3 partes es la solución técnica ideal para empresas que requieren generar múltiples copias de un mismo documento de manera simultánea y automática. Diseñada para impresoras de matriz de punto, este formato cuenta con un papel químico autocopiante de alta calidad en sus tres capas (original y dos copias), todas en color blanco puro para una presentación limpia y uniforme. Su sistema de perforado lateral garantiza un arrastre fluido y sin atascos, mientras que el microperforado facilita el desprendimiento preciso de las hojas. Es el insumo perfecto para la emisión de facturas, remisiones, órdenes de despacho y reportes contables que exigen una distribución inmediata de copias físicas con nitidez profesional.', 194955.00, 20, 44, true, false, 'https://www.abastece.co/abastece/images/76058.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Forma Continua 9 1/2 X 11 1p. Rayada', 'forma-continua-9-12-x-11-1p-rayada-70146', 'Forma Continua 9 1/2&quot; x 11&quot; - 1 Parte (Rayada) ¡Precisión y orden para tus reportes de impresión masiva! La Forma Continua de 9 1/2 x 11 pulgadas en una sola parte es la herramienta estándar para el procesamiento de datos y la generación de listados en impresoras de matriz de punto. Este modelo se destaca por su diseño rayado, que facilita la lectura de datos en columnas y filas, aportando una estructura visual clara para inventarios, reportes contables o nóminas extensas. Fabricada con papel de alta blancura y gramaje uniforme, asegura un arrastre suave y libre de atascos gracias a sus perforaciones laterales de precisión. Además, cuenta con microperforado para un desprendimiento limpio, permitiendo que tus documentos finales mantengan una apariencia profesional y organizada en todo momento.', 108332.00, 20, 51, true, false, 'https://www.abastece.co/abastece/images/70146.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Forma Continua 9 1/2 X 11 2p. Quimico', 'forma-continua-9-12-x-11-2p-quimico-71802', 'Forma Continua 9 1/2&quot; x 11&quot; - 2 Partes (Papel Químico) ¡Duplicado instantáneo y profesional para tu gestión administrativa! La Forma Continua de 9 1/2 x 11 pulgadas en 2 partes es la solución eficiente para empresas que necesitan un registro físico inmediato y una copia fiel para el cliente o archivo. Este formato utiliza papel químico autocopiante de última tecnología, que transfiere la información del original a la copia por presión, eliminando la necesidad de papel carbón y manteniendo las manos y documentos limpios. Diseñada para un rendimiento superior en impresoras de matriz de punto, cuenta con perforaciones laterales reforzadas que garantizan un arrastre constante y sin interrupciones. El microperforado de alta precisión permite separar las hojas de manera rápida y sin rasgaduras. Es el insumo ideal para la impresión de facturas, recibos de caja, remisiones y cualquier documento comercial que requiera agilidad, nitidez y una organización impecable en el flujo de trabajo.', 270480.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/71802.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Forma Continua 9 1/2 X 5 1/2 3P Blanca.', 'forma-continua-9-12-x-5-12-3p-blanca-77328', 'Forma Continua 9 1/2 x 5 1/2 – 3 Partes Blanca Estandarización de documentación contable y optimización de impresión matricial Este insumo estratégico para los departamentos de contabilidad, facturación y control logístico es un suministro de papel químico diseñado específicamente para sistemas de impresión por matriz de puntos. Sus dimensiones técnicas de 9 1/2 x 5 1/2 pulgadas facilitan la estandarización de procesos de emisión de comprobantes, facturas, recibos de caja o remisiones, optimizando el área de impresión para registros comerciales de tamaño medio. La configuración de 3 partes (original y dos copias) en color blanco asegura la continuidad operativa en la generación simultánea de registros físicos para auditoría interna, archivo y entrega al cliente, sin necesidad de duplicar los ciclos de impresión. La precisión en el perforado lateral y el plegado en acordeón de esta forma continua optimiza la eficiencia logística al prevenir atascos en las estaciones de hardware y agilizar el archivo documental, reforzando el bienestar del equipo administrativo al simplificar las tareas de control operativo y garantizar la trazabilidad de la información corporativa.', 200174.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/77328.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Forma Entrada De Almacen Por 50 Minerva 3017', 'forma-entrada-de-almacen-por-50-minerva-3017-0121', 'Forma Entrada de Almacén Minerva 3017 - Bloc x 50 Hojas ¡Control de inventarios preciso y profesional para tu negocio! La Forma de Entrada de Almacén Minerva (Referencia 3017) es la herramienta fundamental para llevar un registro riguroso de los bienes y mercancías que ingresan a tu inventario. Este bloc cuenta con 50 hojas diseñadas con una estructura técnica clara, que permite consignar datos críticos como la fecha de recepción, proveedor, descripción detallada del artículo, cantidades, costos unitarios y firmas de autorización. Fabricado por Minerva, marca líder en papelería comercial, este formato garantiza papel de alta calidad y una impresión nítida que facilita la auditoría y el control administrativo. Su tamaño estándar y diseño funcional lo convierten en el aliado perfecto para bodegas, departamentos de compras y pequeñas empresas que buscan mantener la transparencia y el orden en su cadena de suministro.', 9856.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/0121.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Forma Pagare A Orden Por 12 Minerva 6001', 'forma-pagare-a-orden-por-12-minerva-6001-0277', 'Forma Pagaré a la Orden Minerva 6001 - Bloc x 12 Hojas ¡Respaldo legal y seguridad para tus transacciones financieras! El Pagaré a la Orden Minerva (Referencia 6001) es el instrumento jurídico esencial para formalizar obligaciones de pago y préstamos de manera clara y segura. Este práctico bloc contiene 12 hojas fabricadas con papel de alta calidad, diseñadas bajo estrictos estándares que cumplen con los requisitos legales para su validez como título valor. Su estructura técnica incluye espacios definidos para la identificación de las partes, el monto en letras y números, la fecha de vencimiento, la tasa de interés y las cláusulas de compromiso de pago. Gracias a la confianza que ofrece la marca Minerva, este formato es la solución preferida por comerciantes y particulares para garantizar la transparencia en acuerdos comerciales, facilitando el recaudo y proporcionando un soporte físico profesional para la gestión de deudas.', 12846.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/0277.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Forma Tarjeta De Inventario Fisico X 12 Minerva 3019', 'forma-tarjeta-de-inventario-fisico-x-12-minerva-3019-76234', 'Ficha Técnica: Tarjeta de Inventario Físico Minerva 3019 La tarjeta Minerva 3019 es el formato estándar profesional para la realización de conteos manuales y auditorías de existencias en almacenes, bodegas y centros de distribución. 1. Especificaciones de Producto Este formato está fabricado en cartulina de alta resistencia para garantizar su durabilidad durante el proceso de toma física. Se presenta en paquetes de 100 unidades, con dimensiones aproximadas de media carta, lo que facilita su manipulación en estanterías y su posterior archivo. 2. Campos y Distribución de Información La estructura del formulario incluye secciones para la identificación precisa del artículo (código, descripción y ubicación), así como columnas específicas para el primer y segundo conteo. Esto permite una validación cruzada para minimizar errores humanos en la recolección de datos. 3. Control y Auditoría Para fines de soporte legal y contable, cada tarjeta cuenta con espacios para la fecha del inventario y las firmas del responsable del conteo y del auditor. Es una herramienta indispensable para cumplir con los requerimientos de la revisoría fiscal en cierres anuales. 4. Aplicaciones Recomendadas Su uso principal se centra en inventarios cíclicos, inventarios generales de fin de año, control de activos fijos y procesos de conciliación contra sistemas de información (ERP o software contable).', 47200.00, 20, 24, true, false, 'https://www.abastece.co/abastece/images/76234.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Cosedora Estandar Galvanizado Rapid Caja 5000 U', 'gancho-cosedora-estandar-galvanizado-rapid-caja-5000-u-3772', 'Gancho para Cosedora Estándar Galvanizado Rapid - Caja x 5000 unidades ¡Rendimiento profesional y máxima penetración para un grapado impecable! Los Ganchos Estándar Rapid son el referente de calidad en insumos de oficina, diseñados para ofrecer un desempeño superior en tareas de abrochado de alto volumen. Fabricados en acero galvanizado de alta resistencia, estos ganchos cuentan con puntas ultra-afiladas que garantizan una penetración limpia a través de múltiples hojas sin doblarse ni atascar la cosedora. Su recubrimiento especializado previene la corrosión, protegiendo la integridad de sus documentos a largo plazo. Con una presentación de 5000 unidades por caja, es la solución más rentable y confiable para centros de documentación, notarías, departamentos administrativos y entornos de copiado intensivo.', 3293.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/3772.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Cosedora Galvanizado 23/23 Caja X1000 NHI-313', 'gancho-cosedora-galvanizado-2323-caja-x1000-nhi-313-71458', 'Ganchos para Cosedora Industrial 23/23 Galvanizados - Caja x 1000u. NHI-313 ¡Máxima capacidad de perforación para archivos y documentos extra gruesos! Los Ganchos para Cosedora Industrial NHI-313 (Referencia 23/23) son la solución de alto rendimiento para trabajos de oficina pesados y centros de copiado. Fabricados con acero galvanizado de alta calidad, estos ganchos ofrecen una resistencia estructural superior, evitando que se doblen o se atasquen al enfrentarse a grandes volúmenes de papel. Su diseño de pata extralarga está específicamente desarrollado para perforar con precisión bloques densos de documentos, garantizando un agarre firme y duradero. Gracias a su recubrimiento galvanizado, estos ganchos protegen tus archivos contra la corrosión y las manchas de óxido a largo plazo. La caja por 1000 unidades es ideal para entornos que manejan encuadernaciones, manuales o expedientes legales extensos, asegurando una presentación profesional y una organización impecable en los proyectos más exigentes.', 8526.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/71458.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Lotero No.6 120mm Para Tabla Planillera', 'gancho-lotero-no6-120mm-para-tabla-planillera-74687', 'Gancho Lotero No. 6 (120 mm) para Tabla Planillera ¡Sujeción industrial y máxima capacidad para tus documentos! El Gancho Lotero No. 6 de 120 mm es el accesorio de alto rendimiento diseñado para integrarse perfectamente en tablas planilleras y sistemas de archivo vertical. Fabricado en metal niquelado de gran resistencia, este gancho ofrece una apertura amplia y una presión constante que permite sujetar con total seguridad grandes volúmenes de papel, formularios o planos sin que se deslicen. Su diseño ergonómico y sistema de resorte reforzado lo convierten en la herramienta indispensable para ingenieros, personal de logística y oficinas que requieren un manejo ágil y duradero de documentos de uso frecuente en condiciones exigentes.', 2981.00, 20, 21, true, false, 'https://www.abastece.co/abastece/images/74687.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Plano(herraje Planillero) Metalico 10x3cm', 'gancho-planoherraje-planillero-metalico-10x3cm-75389', 'Gancho Plano (Herraje Planillero) Metálico - 10 x 3 cm ¡Estabilidad y firmeza para tus tablas de soporte y carpetas! El Gancho Plano Metálico de 10 x 3 cm es el herraje técnico ideal para la fabricación o reparación de tablas planilleras, carpetas de legajado y sistemas de archivo móvil. Fabricado en acero de alta resistencia con acabado niquelado para prevenir la corrosión, este componente ofrece un mecanismo de presión firme y seguro que mantiene las hojas perfectamente alineadas y en su lugar. Su diseño compacto y perfil bajo permite una manipulación cómoda de los documentos, siendo la solución perfecta para profesionales en campo, personal de logística o entornos de oficina que exigen una herramienta de sujeción duradera, ligera y de fácil instalación.', 1646.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/75389.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Plastiflecha R. Liviana Y Pesada X5000u.', 'gancho-plastiflecha-r-liviana-y-pesada-x5000u-71374', 'Gancho Plastiflecha para Referencia Liviana y Pesada - Caja x 5000 unidades ¡Versatilidad técnica y sujeción garantizada para todo tipo de textiles y materiales! El Gancho Plastiflecha (Fastener) Multiuso es la solución integral para el etiquetado en entornos de alta producción. Diseñado específicamente para ser compatible con agujas de referencia liviana y pesada, este insumo se adapta con precisión tanto a telas delicadas como a materiales más densos (denim, lona o cuero) sin comprometer la integridad de la fibra. Fabricado en polímero de alta resistencia, garantiza una fijación segura de etiquetas de precio y marca, resistiendo la manipulación constante en puntos de venta. Su diseño optimizado asegura una alimentación continua en la pistola etiquetadora, minimizando los tiempos de inactividad por atascos. Es el insumo indispensable para fábricas de confección, marroquinerías, almacenes de cadena y centros de distribución logística.', 12748.00, 20, 16, true, false, 'https://www.abastece.co/abastece/images/71374.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Plastiflecha Verde Manual X 5000 Und', 'gancho-plastiflecha-verde-manual-x-5000-und-76139', 'Gancho Plastiflecha Verde Manual - Caja x 5000 Unidades ¡Identificación ágil y segura para tus productos y textiles! El Gancho Plastiflecha Verde es la solución estándar para el etiquetado manual en la industria textil, calzado y comercio en general. Fabricado en polipropileno de alta densidad, este sujetador ofrece una resistencia óptima para asegurar etiquetas de precio, marca o talla sin riesgo de desprendimiento accidental. Su vibrante color verde permite una rápida identificación visual o codificación por categorías en almacenes y puntos de venta. Con una presentación de 5000 unidades, garantiza un alto rendimiento en tareas de etiquetado masivo, siendo compatible con la mayoría de pistolas flechadoras estándar para un acabado limpio, rápido y profesional en cada prenda o artículo.', 14823.00, 20, 37, true, false, 'https://www.abastece.co/abastece/images/76139.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Gancho Yoyo Carnet Negro Unidad', 'gancho-yoyo-carnet-negro-unidad-77594', 'Gancho Yoyo Carnet Negro Unidad ¡Asegure el control de acceso, facilite la identificación del personal y garantice la funcionalidad en el porte de credenciales! Garantice la visibilidad permanente de las credenciales corporativas, agilice el marcaje en lectores de seguridad e identifique rápidamente a sus colaboradores y visitantes en las instalaciones de la empresa. El uso del gancho yoyo carnet negro unidad facilita la estandarización de procesos en el sistema de identificación, control de accesos y seguridad física de la compañía, unificando la presentación de la dotación para sus departamentos de gestión humana, seguridad y operaciones. Su cable retráctil de alta resistencia, clip de sujeción firme y acabado negro sobrio aseguran la continuidad operativa durante la jornada laboral, permitiendo extender la escarapela hacia los puntos de lectura marcando fluidez en los torniquetes sin correr el riesgo de pérdidas ni desgastes en la prenda del usuario. Incorpore este producto a sus adquisiciones para elevar la eficiencia logística en las compras de insumos para identificación y dotación corporativa, impulsando el bienestar del equipo al proveer un accesorio cómodo, práctico y de excelente presentación personal.', 623.00, 20, 26, true, false, 'https://www.abastece.co/abastece/images/77594.jpg'),
